//! Handler utilities for the various selection protocols.
//!
//! Wayland originally only had a singe way to deal with the user clipboard with the help of
//! `wl_data_device` protocol. However the demand for *primary* selection as well as writing
//! clipboard managers made it into developing protocol extension for the said cases.
//!
//! The following selection providers are supported:
//!
//! - The [`data_device`](data_device/index.html) module to work with the traditional clipboard selection.
//! - The [`primary_selection`](primary_selection/index.html) module to work with the primary selection.
//! - The [`wlr_data_control`](wlr_data_control/index.html) module to hook data control into
//!   clipboard and primary selection

use std::os::unix::io::OwnedFd;

use wayland_server::backend::ClientId;

use crate::input::{Seat, SeatHandler};

pub mod data_device;
pub mod ext_data_control;
pub mod primary_selection;
pub mod wlr_data_control;

mod device;
mod offer;
mod seat_data;
mod source;

pub use source::SelectionSource;

/// compd hook 3: the selection targets on `seat` that `owned_by` still holds,
/// read under a SCOPED borrow, then — with no borrow held — a replacement asked
/// for each from [`SelectionHandler::selection_source_destroyed`] and installed in
/// ONE transition (or the target cleared when the handler declines). The scoped
/// borrow is the contract the clipboard path established: the handler gets
/// `&mut D` and may touch seat state.
pub(crate) fn replace_owned_selections<D>(
    state: &mut D,
    dh: &wayland_server::DisplayHandle,
    seat: &Seat<D>,
    owned_by: impl Fn(&source::SelectionSourceProvider) -> bool,
) where
    D: SelectionHandler + 'static,
{
    use std::cell::RefCell;
    let seat_data = seat
        .user_data()
        .get::<RefCell<seat_data::SeatData<D::SelectionUserData>>>()
        .unwrap();
    let owned: Vec<SelectionTarget> = {
        let data = seat_data.borrow();
        [SelectionTarget::Clipboard, SelectionTarget::Primary]
            .into_iter()
            .filter(|target| {
                let current = match target {
                    SelectionTarget::Clipboard => data.get_clipboard_selection(),
                    SelectionTarget::Primary => data.get_primary_selection(),
                };
                matches!(current, Some(offer::OfferReplySource::Client(p)) if owned_by(p))
            })
            .collect()
    };
    for target in owned {
        let replacement = state
            .selection_source_destroyed(target, seat)
            .map(|(mime_types, user_data)| {
                offer::OfferReplySource::Compositor(source::CompositorSelectionProvider {
                    ty: target,
                    mime_types,
                    user_data,
                })
            });
        let mut data = seat_data.borrow_mut();
        match target {
            SelectionTarget::Clipboard => data.set_clipboard_selection::<D>(dh, replacement),
            SelectionTarget::Primary => data.set_primary_selection::<D>(dh, replacement),
        }
    }
}

/// Events that are generated by interactions of the clients with the data device.
pub trait SelectionHandler: Sized + SeatHandler {
    /// UserData attached to server-side selections.
    type SelectionUserData: Clone + Send + Sync + 'static;

    /// A client has set the selection
    #[allow(unused_variables)]
    fn new_selection(&mut self, ty: SelectionTarget, source: Option<SelectionSource>, seat: Seat<Self>) {}

    /// The client owning the `ty` selection is gone and the selection is about to be
    /// cleared.
    ///
    /// Return `Some((mime_types, user_data))` to install a compositor-provided
    /// replacement **atomically in place of the clear**, or `None` to let the selection
    /// be cleared as usual (the default).
    ///
    /// This exists so a compositor that persists the clipboard across client exit does
    /// not have to clear-then-refill: that sequence makes clients observe a
    /// `wl_data_device.selection(nil)` immediately followed by a fresh offer, and apps
    /// act on the `nil` (greying out Paste, dropping cached offer state).
    ///
    /// Called with no borrow held on the seat's selection data, so the implementation
    /// may touch seat state — but it must not re-enter the selection API itself.
    /// compd hook 3a: a client's
    /// selection source is gone — destroyed or its client disconnected — whether or
    /// not it owned a selection. Called FIRST from all four protocols' `destroyed()`
    /// (data device, primary selection, wlr- and ext-data-control), before any
    /// ownership test or replacement, so mirrors (a second seat's copy, a relay) can
    /// invalidate their offers immediately, without polling. Default: nothing.
    #[allow(unused_variables)]
    fn selection_source_gone(&mut self, source: SelectionSource) {}

    /// compd hook: see the doc above. compd extends it beyond the
    /// clipboard: it is now consulted for the PRIMARY selection too, and for a
    /// data-control source that owned either target, so persistence can cover
    /// middle-click and `wl-copy` as well as `wl_data_device`.
    #[allow(unused_variables)]
    fn selection_source_destroyed(
        &mut self,
        ty: SelectionTarget,
        seat: &Seat<Self>,
    ) -> Option<(Vec<String>, Self::SelectionUserData)> {
        None
    }

    /// A client requested to read the server-set selection.
    ///
    /// * `mime_type` - the requested mime type
    /// * `fd` - the fd to write into
    /// * `client` - the client that asked, so a compositor writing asynchronously can tell
    ///   which transfers belong together. A client may `receive` several mime types at once
    ///   and drain them in sequence, which leaves the pipes it has not reached yet looking
    ///   idle; without an identity to group by, those are indistinguishable from a client
    ///   that stopped reading altogether.
    #[allow(unused_variables)]
    fn send_selection(
        &mut self,
        ty: SelectionTarget,
        mime_type: String,
        fd: OwnedFd,
        seat: Seat<Self>,
        user_data: &Self::SelectionUserData,
        client: ClientId,
    ) {
    }
}

/// The target for the selection request.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SelectionTarget {
    /// The target for the request is primary selection.
    Primary,
    /// The target for the request is clipboard selection.
    Clipboard,
}

pub(crate) mod private {
    /// `selection_dispatch!(self; Enum(foo) => foo.something())`
    /// expands to the equivalent of
    /// ```ignore
    /// match self {
    ///    Enum::DataDevice(foo) => foo.something(),
    ///    Enum::Primary(foo) => foo.something(),
    ///    Enum::WlrDataControl(foo) => foo.something(),
    ///    Enum::ExtDataControl(foo) => foo.something(),
    /// }
    /// ```
    ///
    /// And `selection_dispatch!(self, other; Enum(foo), EnumNext(zoo) => foo.something(zoo))` expands
    /// to the equivalent of
    /// ```ignore
    /// match (self, other) {
    ///    (Enum::DataDevice(foo), EnumNext::DataDevice(zoo))  => foo.something(zoo),
    ///    (Enum::Primary(foo), EnumNext::Primary(zoo))  => foo.something(zoo),
    ///    (Enum::WlrDataControl(foo), EnumNext::WlrDataControl(zoo))  => foo.something(zoo),
    ///    (Enum::ExtDataControl(foo), EnumNext::ExtDataControl(zoo))  => foo.something(zoo),
    ///    _ => unreachable!(),
    /// }
    /// ```
    ///
    /// The result can be converted to another enum by adding `; as AnotherEnum`
    macro_rules! selection_dispatch {
        ($what:ident; $enum:ident ( $($c1:tt)* ) => $x:expr) => {
            match $what {
                $enum::DataDevice($($c1)*) => $x,
                $enum::Primary($($c1)*) => $x,
                $enum::WlrDataControl($($c1)*) => $x,
                $enum::ExtDataControl($($c1)*) => $x,
            }
        };
        ($what:ident$(, $what_next:ident)+; $enum:ident ( $($c1:tt)*) $(, $enum_next:ident ( $($c2:tt)* ) )+ => $x:expr) => {
            match ($what$(, $what_next)*) {
                ($enum::DataDevice($($c1)*)$(, $enum_next::DataDevice($($c2)*))*) => $x,
                ($enum::Primary($($c1)*)$(, $enum_next::Primary($($c2)*))*) => $x,
                ($enum::WlrDataControl($($c1)*)$(, $enum_next::WlrDataControl($($c2)*))*) => $x,
                ($enum::ExtDataControl($($c1)*)$(, $enum_next::ExtDataControl($($c2)*))*) => $x,
                _ => unreachable!(),
            }
        };
    }

    pub(crate) use selection_dispatch;
}

// compd hook 3 guard (source guard: a behavioural test needs live clients on
// every protocol). Every protocol's `destroyed()` reports `selection_source_gone`
// before anything else, and hands ownership to the shared replacement path.
#[cfg(test)]
mod hook3_guard {
    const SOURCES: [(&str, &str); 4] = [
        ("data_device", include_str!("data_device/source.rs")),
        ("primary_selection", include_str!("primary_selection/source.rs")),
        ("wlr_data_control", include_str!("wlr_data_control/source.rs")),
        ("ext_data_control", include_str!("ext_data_control/source.rs")),
    ];

    #[test]
    fn every_source_reports_gone_first_then_offers_replacement() {
        for (name, src) in SOURCES {
            let body = &src[src.find("fn destroyed(").unwrap_or_else(|| panic!("{name}: destroyed"))..];
            let gone = body.find("selection_source_gone(").unwrap_or_else(|| panic!("{name}: no gone hook"));
            let used = body.find("used_sources").unwrap_or_else(|| panic!("{name}: used_sources"));
            assert!(gone < used, "{name}: gone must be reported before the ownership bookkeeping");
            assert!(
                body.contains("replace_owned_selections("),
                "{name}: an owning source must go through the replacement path"
            );
        }
    }
}
